const message = $json.message?.text || "";

const fields = {};

for (const line of message.split(/\r?\n/)) {
  const separator = line.indexOf(":");

  if (separator === -1) continue;

  const key = line.slice(0, separator).trim().toLowerCase();
  const value = line.slice(separator + 1).trim();

  fields[key] = value;
}

const topic = fields.topic;
const audience = fields.audience;
const language = fields.language;

// Supports: 10, 10 seconds, 10 sec, 10s
const durationMatch = fields.duration?.match(
  /^\s*(\d+(?:\.\d+)?)\s*(?:seconds?|secs?|s)?\s*$/i
);

const duration = durationMatch
  ? Number(durationMatch[1])
  : NaN;

if (
  !topic ||
  !audience ||
  !language ||
  !Number.isFinite(duration) ||
  duration <= 0
) {
  throw new Error(
    "Invalid format. Required: Topic, Audience, Language, Duration"
  );
}

return [
  {
    json: {
      topic,
      audience,
      language,
      duration_seconds: duration,
      telegram_chat_id: $json.message.chat.id
    }
  }
];

